/bin/bash -c "python3 - <<'PY'
from itertools import product, combinations
from fractions import Fraction

def sign(v):
 return (v>0)-(v<0)
xs=[-1,0,1]
ys=[1,-1,1]
def loss(a,b):
 return sum(sign(a*x+b)"'!=y for x,y in zip(xs,ys))
print('"'Nonseparable one-dimensional example:', list(zip(xs,ys)))
print('Classifier x-1/2 loss:',loss(1,Fraction(-1,2)))
for t,a in product(xs,[1,-1]):
 e=loss(a,-a*t)
 print('Threshold',t,'orientation',a,'loss',e,'actual reversed loss',loss(-a,a*t),'Theorem 5 reversed loss',len(xs)-1-e)
pts=[(-5,0),(-4,3),(-3,-4),(0,5),(3,-4),(4,3)]
def area(a,b,c):
 return (b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0])
print('Six planar points:',pts)
print('No three collinear:',all(area(*triple)"'!=0 for triple in combinations(pts,3)))
print('"'Distinct first coordinates:',len({x for x,y in pts})==len(pts))
print('All lifted points satisfy x"'^2+y''^2-25=0:'"',all(x*x+y*y==25 for x,y in pts))
PY"
